interface TodoRepository {
    Todo simpan(String judul);

    List<Todo> semua();

    Todo cari(int id);

    boolean hapus(int id);

    void perbarui(Todo todo);
}

class TodoRepositoryJpa implements TodoRepository {
    private final EntityManagerFactory emf;

    TodoRepositoryJpa(EntityManagerFactory emf) {
        this.emf = emf;
    }

    private <T> T dalamTransaksi(Function<EntityManager, T> kerja) {
        EntityManager em = emf.createEntityManager();
        try {
            em.getTransaction().begin();
            T hasil = kerja.apply(em);
            em.getTransaction().commit();
            return hasil;
        } catch (RuntimeException e) {
            if (em.getTransaction().isActive()) {
                em.getTransaction().rollback();
            }
            throw e;
        } finally {
            em.close();
        }
    }

    public Todo simpan(String judul) {
        return dalamTransaksi(em -> {
            Todo t = new Todo(judul);
            em.persist(t);
            return t;
        });
    }

    public List<Todo> semua() {
        return dalamTransaksi(em -> em.createQuery("select t from Todo t order by t.id", Todo.class).getResultList());
    }

    public Todo cari(int id) {
        return dalamTransaksi(em -> em.find(Todo.class, id));
    }

    public boolean hapus(int id) {
        return dalamTransaksi(em -> {
            Todo t = em.find(Todo.class, id);
            if (t == null) {
                return false;
            }
            em.remove(t);
            return true;
        });
    }

    public void perbarui(Todo todo) {
        dalamTransaksi(em -> em.merge(todo));
    }
}

class Jpa {
    static EntityManagerFactory buat(boolean tampilkanSql, Class<?>... entity) {
        Configuration cfg = new Configuration()
                .setProperty("hibernate.connection.url", "jdbc:h2:mem:toko;DB_CLOSE_DELAY=-1")
                .setProperty("hibernate.connection.username", "sa")
                .setProperty("hibernate.hbm2ddl.auto", "create")
                .setProperty("hibernate.show_sql", String.valueOf(tampilkanSql));
        for (Class<?> k : entity) {
            cfg.addAnnotatedClass(k);
        }
        return cfg.buildSessionFactory();
    }
}

